static
void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;

#pragma scop
  {
    int t, i, ii, i_end;
#define JACOBI_1D_TILE 2048
#pragma omp parallel default(none) shared(A, B, n, tsteps) private(t, i, ii, i_end)
    {
      for (t = 0; t < _PB_TSTEPS; t++)
	{
#pragma omp for schedule(static)
	  for (ii = 1; ii < _PB_N - 1; ii += JACOBI_1D_TILE)
	    {
	      i_end = ii + JACOBI_1D_TILE;
	      if (i_end > _PB_N - 1) i_end = _PB_N - 1;
